<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Support\{Request,Response};
final class AdminOverviewController extends Controller {public function index(Request $r):Response{$db=app('database');$metrics=['users'=>0,'active'=>0,'suspended'=>0,'restricted'=>0,'global'=>0,'enabled_countries'=>0,'disabled_countries'=>0,'licenses_missing'=>0,'licenses_expired'=>0];if($db){$metrics['users']=(int)$db->scalar('SELECT COUNT(*) FROM users');foreach(['active','suspended','restricted']as$s)$metrics[$s]=(int)$db->scalar('SELECT COUNT(*) FROM users WHERE account_status=?',[$s]);$metrics['global']=(int)$db->scalar('SELECT COUNT(*) FROM users u INNER JOIN countries c ON c.id=COALESCE(u.assigned_country_id,u.country_id) WHERE c.is_global=1');$metrics['enabled_countries']=(int)$db->scalar('SELECT COUNT(*) FROM countries WHERE is_enabled=1');$metrics['disabled_countries']=(int)$db->scalar('SELECT COUNT(*) FROM countries WHERE is_enabled=0');}$recent=$db?$db->select('SELECT first_name,last_name,email,created_at FROM users ORDER BY created_at DESC LIMIT 6'):[];return $this->view('admin.index',['title'=>'Administration','metrics'=>$metrics,'recent'=>$recent],'layouts.admin');}}
